pub assume_specification<T, S, A: Allocator>[
    HashSet::<T, S, A>::capacity
](set: &HashSet<T, S, A>) -> (capacity: usize)
    ensures
        capacity >= set.len(),
;

pub assume_specification<T: Eq + Hash, S: BuildHasher, A: Allocator>[
    HashSet::<T, S, A>::shrink_to
](
    set: &mut HashSet<T, S, A>,
    min_capacity: usize,
)
    ensures
        final(set)@ == old(set)@,
;

pub assume_specification<T: Eq + Hash, S: BuildHasher, A: Allocator>[
    HashSet::<T, S, A>::shrink_to_fit
](
    set: &mut HashSet<T, S, A>,
)
    ensures
        final(set)@ == old(set)@,
;

pub assume_specification<T: Eq + Hash, S: BuildHasher, A: Allocator>[
    HashSet::<T, S, A>::try_reserve
](
    set: &mut HashSet<T, S, A>,
    additional: usize,
) -> (result: Result<(), TryReserveError>)
    ensures
        final(set)@ == old(set)@,
;

pub assume_specification<T, S>[
    HashSet::<T, S>::with_capacity_and_hasher
](
    capacity: usize,
    hasher: S,
) -> (result: HashSet<T, S>)
    ensures
        result@ == Set::<T>::empty(),
;
